const http = require("http");

const PORT = Number(process.env.PORT || 3000);
const CLICKHOUSE_URL = process.env.CLICKHOUSE_URL;
const METRICS_QUERY = "SELECT sum(value) AS total FROM analytics.metrics FORMAT JSONEachRow";

async function queryMetricsTotal() {
  if (!CLICKHOUSE_URL) {
    throw new Error("Missing CLICKHOUSE_URL");
  }

  const response = await fetch(CLICKHOUSE_URL, {
    method: "POST",
    headers: {
      "content-type": "text/plain; charset=utf-8",
    },
    body: METRICS_QUERY,
  });

  if (!response.ok) {
    const body = await response.text();
    throw new Error(`ClickHouse query failed with status ${response.status}: ${body}`);
  }

  const payload = (await response.text()).trim();
  if (!payload) {
    return 0;
  }

  const row = JSON.parse(payload);
  return Number(row?.total ?? 0);
}

function writeJson(res, statusCode, body) {
  res.writeHead(statusCode, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

const server = http.createServer(async (req, res) => {
  if (req.url !== "/api/metrics") {
    writeJson(res, 404, { error: "Not found" });
    return;
  }

  try {
    const total = await queryMetricsTotal();
    writeJson(res, 200, { total });
  } catch (error) {
    writeJson(res, 500, {
      error: error instanceof Error ? error.message : String(error),
    });
  }
});

server.listen(PORT, () => {
  console.log(`API on :${PORT}`);
});
